select left(stem,80) from questions q join subject_groups g on g.id=q.subject_group_id where g.code='medical-science' and (stem ilike '%sickle%' or stem ilike '%scurvy%' or stem ilike '%appendix%' or stem ilike '%bile%' or stem ilike '%ECG%' or stem ilike '%thyroid%' or stem ilike '%rabies%' or stem ilike '%measles%' or stem ilike '%lens%' or stem ilike '%myopia%' or stem ilike '%pepsin%' or stem ilike '%villi%' or stem ilike '%alveoli%' or stem ilike '%neuron%' or stem ilike '%litmus%' or stem ilike '%isotope%' or stem ilike '%Newton%' or stem ilike '%specific heat%' or stem ilike '%dialysis%' or stem ilike '%vaccine%');
